    "about.seoTitle": "About Us | QuoteAI — AI Quoting Software for Tradespeople",
    "about.seoDescription": "QuoteAI was built to free Canadian tradespeople from paperwork. Discover our mission: professional quotes in 30 seconds thanks to artificial intelligence.",
    "about.madeIn": "Made in Canada",
    "about.heroTitlePrefix": "We are QuoteAI.",
    "about.heroTitleHighlight": "Freeing tradespeople from paperwork.",
    "about.heroBody": "There are over 1.2 million tradespeople and independent professionals across Canada. Each of them loses an average of 3-4 hours a week putting together quotes by hand. We built QuoteAI to give that time back.",
    "about.storyTitle": "How the idea was born",
    "about.storyP1": "It all started with a real frustration: a painter in Toronto who, every evening after a full day on site, still had to sit down at the computer to update spreadsheets and send quotes to clients. It often took an hour and a half for a $200 job.",
    "about.storyP2": "We thought: artificial intelligence already knows how to put together a professional quote. Why not let a tradesperson describe the job the way they'd explain it out loud, and get a ready-to-send document back in 30 seconds?",
    "about.storyP3": "That's how QuoteAI was born. Software built specifically for Canadian trades, with the right terminology, Canadian market pricing, and everything needed: company logo, business number, GST/HST, customizable terms, and a professional PDF.",
    "about.valuesTitle": "Our values",
    "about.valuesSubtitle": "Every decision we make starts from three core principles.",
    "about.value1Title": "Real speed",
    "about.value1Body": "30 seconds isn't a slogan. It's how long it takes to generate a complete, professional quote. Your time matters.",
    "about.value2Title": "Built for the trades",
    "about.value2Body": "Not a generic tool with a fresh coat of paint. Built from the ground up for Canadian trades: job categories, pricing, tax rules, and language.",
    "about.value3Title": "Simplicity first",
    "about.value3Body": "No courses or tutorials needed. If you can write a text message, you can use QuoteAI. The technology should disappear — only the result should remain.",
    "about.whoTitle": "Who QuoteAI is for",
    "about.whoP1Prefix": "QuoteAI is built for",
    "about.whoP1Strong": "tradespeople, construction businesses, technicians, and independent professionals across Canada",
    "about.whoP1Suffix": "who work on a job-by-job basis and need to present quotes to their clients.",
    "about.whoP2": "Painters, electricians, plumbers, masons, carpenters, surveyors, architects, tilers, landscapers, window and door installers, HVAC technicians, and many more. If your work means telling a client what a job will cost before you do it, QuoteAI is for you.",
    "about.whoP3": "We're already used by tradespeople across the country: from Toronto to Vancouver, from Montreal to Calgary.",
    "about.ctaTitle": "Try QuoteAI for free",
    "about.ctaBody": "Create your first quote in 30 seconds. No credit card required.",
    "about.ctaStartFree": "Start for free",
    "about.ctaContactUs": "Contact us",

    "contact.seoTitle": "Contact | QuoteAI — Help & Support",
    "contact.seoDescription": "Have questions about QuoteAI? Contact us by email or WhatsApp. We're here to help you generate professional quotes faster.",
    "contact.heroTitlePrefix": "How can we",
    "contact.heroTitleHighlight": "help?",
