    "contact.responseTimeBodyStrong": "4-8 hours on business days",
    "contact.responseTimeBodySuffix": "(Monday–Friday, 9:00 AM–6:00 PM ET). For requests sent over the weekend, we reply Monday morning.",
    "contact.faqTitle": "Frequently asked questions",
    "contact.faq1Q": "Can I cancel my subscription at any time?",
    "contact.faq1A": "Yes. You can cancel your subscription at any time from your account settings, with no penalties or extra fees. You'll keep access until the end of your paid period.",
    "contact.faq2Q": "Do you offer a discount for agencies or teams?",
    "contact.faq2A": "Yes. For multi-user or high-volume use, contact us at info@quoteai.ca and we'll find the right plan for you.",
    "contact.faq3Q": "Is my data and my quotes secure?",
    "contact.faq3A": "Yes. All data is encrypted in transit (TLS) and at rest. We never share your data with third parties. Read our Privacy Policy for details.",
    "contact.faq4Q": "Can I import my own price list?",
    "contact.faq4A": "Yes. From Settings → Price List you can enter your own custom pricing, which the AI will use as a reference for your quotes.",
