    "seo.guide.heading": "Complete guide: how to create a professional quote",
    "seo.guide.subtitle": "Follow these 5 steps to create a quote your client will sign right away",
    "seo.guide.step1Title": "Gather the job information",
    "seo.guide.step1Body": "Before you start, make sure you have: the type of job, approximate dimensions (sq ft, linear ft, units), materials the client wants, and the client's details (name, address, email). With quoteai you can capture all of this right from your phone during the site visit.",
    "seo.guide.step2Title": "Define your line items",
    "seo.guide.step2Body": "A professional quote separates labour and materials. Every line item needs: a detailed description, a unit of measure (sq ft, linear ft, hours, lump sum), a quantity, a unit price, and a total. quoteai's AI generates this structure automatically from your description.",
    "seo.guide.step3Title": "Apply the right tax rate",
    "seo.guide.step3Body": "Tax rules vary by province in Canada — GST, HST, or GST+PST depending on where you work. Getting the tax wrong can be costly. quoteai applies the right rate automatically based on the job and location you describe.",
    "seo.guide.step4Title": "Add your payment terms",
    "seo.guide.step4Body": "Always spell out the terms: deposit required (e.g. 30% upon acceptance), balance due on completion, accepted payment methods (e-transfer, cheque, card), estimated timeline, and how long the quote is valid (typically 30 days).",
    "seo.guide.step5Title": "Send the quote to your client",
    "seo.guide.step5Body": "PDF is the best format: it can't be accidentally edited and opens on any device. Send it by email or WhatsApp. With quoteai, download the PDF in one click, already formatted with your company header and logo.",

