    "whatsapp.seoTitle": "Quotes on WhatsApp – QuoteAI | Canada's First AI Quoting Bot",
    "whatsapp.seoDescription": "Describe the job by voice, text, or photo on WhatsApp. QuoteAI generates a professional quote with a PDF in 60 seconds. A first for Canadian trades.",
    "whatsapp.feature1Title": "Voice, text or photo",
    "whatsapp.feature1Desc": "Send a voice note from the truck, type from the job site, or snap a photo of your notes. The AI understands it all and generates the quote.",
    "whatsapp.feature2Title": "Quote in 60 seconds",
    "whatsapp.feature2Desc": "Chapters, cost line items, tax and totals calculated instantly. Zero formulas, zero Excel.",
    "whatsapp.feature3Title": "PDF delivered in chat",
    "whatsapp.feature3Desc": "The professional document arrives right on WhatsApp. Forward it to your client with a tap.",
    "whatsapp.step1Title": "Send a voice note, text or photo",
    "whatsapp.step1Desc": "Right on WhatsApp. Describe the job the way you'd explain it to a client.",
    "whatsapp.step2Title": "The AI generates the preview",
    "whatsapp.step2Desc": "Chapters, prices and tax in 60 seconds. You can correct it or approve it right away.",
    "whatsapp.step3Title": "Get the PDF in chat",
    "whatsapp.step3Desc": "Send it to your client with a tap. The quote is also saved on quoteai.ca.",
    "whatsapp.badgeNew": "NEW · A Canadian First",
    "whatsapp.heroTitlePrefix": "Your quotes,",
    "whatsapp.heroTitleHighlight": "right on WhatsApp",
    "whatsapp.heroBody": "Send a voice note from the job site. QuoteAI generates the professional quote, shows you a preview, and sends you the PDF — without opening a single app.",
