    "footer.fine": "quoteai est une plateforme de soumission canadienne pour entrepreneurs et petites entreprises. La TPS/TVH est calculée automatiquement selon la province et les informations d'entreprise sont appliquées à chaque soumission. Les paiements sont traités par Stripe; les sessions sont protégées par des cookies chiffrés. Forfaits : Starter 19 $ (10 soumissions), Pro 49 $ (60 soumissions), Elite 59 $ (illimité); soumissions à l'unité de 5 $ à 13 $. Les fonctionnalités, la disponibilité et les prix peuvent changer sans préavis.",
