    "about.seoTitle": "À propos | QuoteAI — Logiciel de soumission par IA pour artisans",
    "about.seoDescription": "QuoteAI a été créé pour libérer les artisans canadiens de la paperasse. Découvrez notre mission : des soumissions professionnelles en 30 secondes grâce à l'intelligence artificielle.",
    "about.madeIn": "Conçu au Canada",
    "about.heroTitlePrefix": "Nous sommes QuoteAI.",
    "about.heroTitleHighlight": "Nous libérons les artisans de la paperasse.",
    "about.heroBody": "Il y a plus de 1,2 million d'artisans et de travailleurs autonomes au Canada. Chacun d'eux perd en moyenne 3 à 4 heures par semaine à préparer des soumissions à la main. Nous avons créé QuoteAI pour leur redonner ce temps.",
    "about.storyTitle": "Comment l'idée est née",
    "about.storyP1": "Tout a commencé par une frustration bien réelle : un peintre de Toronto qui, chaque soir après une longue journée de chantier, devait encore s'asseoir devant l'ordinateur pour mettre à jour ses feuilles de calcul et envoyer des soumissions à ses clients. Cela lui prenait souvent une heure et demie pour un contrat de 200$.",
    "about.storyP2": "Nous nous sommes dit : l'intelligence artificielle sait déjà comment préparer une soumission professionnelle. Pourquoi ne pas permettre à un artisan de décrire le travail comme il le raconterait à voix haute, et recevoir en 30 secondes un document prêt à envoyer?",
    "about.storyP3": "C'est ainsi qu'est né QuoteAI. Un logiciel conçu spécifiquement pour les métiers canadiens, avec la bonne terminologie, les prix du marché canadien, et tout ce qu'il faut : logo de l'entreprise, numéro d'entreprise, TPS/TVH, conditions personnalisables, PDF professionnel.",
    "about.valuesTitle": "Nos valeurs",
    "about.valuesSubtitle": "Chaque décision que nous prenons repose sur trois principes fondamentaux.",
    "about.value1Title": "Une vraie rapidité",
    "about.value1Body": "30 secondes, ce n'est pas un slogan. C'est le temps qu'il faut pour générer une soumission complète et professionnelle. Votre temps compte.",
    "about.value2Title": "Pensé pour les métiers",
    "about.value2Body": "Pas un outil générique repeint à la hâte. Conçu dès le départ pour les métiers canadiens : catégories de travaux, prix, règles fiscales et langue.",
    "about.value3Title": "La simplicité avant tout",
    "about.value3Body": "Pas besoin de cours ni de tutoriels. Si vous savez écrire un texto, vous savez utiliser QuoteAI. La technologie doit s'effacer, seul le résultat doit rester.",
    "about.whoTitle": "Pour qui est QuoteAI",
    "about.whoP1Prefix": "QuoteAI est conçu pour",
    "about.whoP1Strong": "les artisans, les entreprises de construction, les techniciens et les travailleurs autonomes partout au Canada",
    "about.whoP1Suffix": "qui travaillent à la commande et doivent présenter des soumissions à leurs clients.",
    "about.whoP2": "Peintres, électriciens, plombiers, maçons, charpentiers, arpenteurs, architectes, carreleurs, paysagistes, installateurs de portes et fenêtres, techniciens en CVC, et bien d'autres. Si votre travail exige d'expliquer à un client combien coûtera une intervention avant de la réaliser, QuoteAI est pour vous.",
    "about.whoP3": "Nous sommes déjà utilisés par des artisans partout au pays : de Toronto à Vancouver, de Montréal à Calgary.",
    "about.ctaTitle": "Essayez QuoteAI gratuitement",
    "about.ctaBody": "Créez votre première soumission en 30 secondes. Aucune carte de crédit requise.",
    "about.ctaStartFree": "Commencer gratuitement",
    "about.ctaContactUs": "Nous contacter",

    "contact.seoTitle": "Contact | QuoteAI — Aide et soutien",
    "contact.seoDescription": "Des questions sur QuoteAI? Contactez-nous par courriel ou WhatsApp. Nous sommes là pour vous aider à générer des soumissions professionnelles plus rapidement.",
    "contact.heroTitlePrefix": "Comment pouvons-nous",
    "contact.heroTitleHighlight": "vous aider?",
    "contact.heroBody": "L'équipe QuoteAI répond en quelques heures les jours ouvrables. Choisissez le canal que vous préférez.",
    "contact.productSupportTitle": "Soutien produit",
    "contact.productSupportBody": "Problèmes techniques, questions d'utilisation, demandes de fonctionnalités.",
    "contact.whatsappBody": "Vous voulez essayer le service sur WhatsApp ou avez une question rapide? Écrivez-nous directement.",
    "contact.whatsappLink": "Découvrez QuoteAI sur WhatsApp",
    "contact.privacyLegalTitle": "Confidentialité et juridique",
    "contact.privacyLegalBody": "Demandes relatives à la vie privée, exercice de vos droits, questions légales ou contractuelles.",
    "contact.responseTimeTitle": "Délais de réponse",
    "contact.responseTimeBodyPrefix": "Nous répondons à tous les courriels en",
    "contact.responseTimeBodyStrong": "4 à 8 heures les jours ouvrables",
    "contact.responseTimeBodySuffix": "(lundi–vendredi, 9 h–18 h HE). Pour les demandes envoyées la fin de semaine, nous répondons le lundi matin.",
    "contact.faqTitle": "Questions fréquentes",
    "contact.faq1Q": "Puis-je annuler mon abonnement à tout moment?",
    "contact.faq1A": "Oui. Vous pouvez annuler votre abonnement à tout moment depuis les paramètres de votre compte, sans pénalité ni frais supplémentaires. Vous conserverez l'accès jusqu'à la fin de la période déjà payée.",
    "contact.faq2Q": "Offrez-vous un rabais pour les agences ou les équipes?",
    "contact.faq2A": "Oui. Pour une utilisation multi-utilisateurs ou à volume élevé, contactez-nous à info@quoteai.ca et nous trouverons la solution qui vous convient.",
    "contact.faq3Q": "Mes données et mes soumissions sont-elles en sécurité?",
    "contact.faq3A": "Oui. Toutes les données sont chiffrées en transit (TLS) et au repos. Nous ne partageons jamais vos données avec des tiers. Consultez notre politique de confidentialité pour plus de détails.",
    "contact.faq4Q": "Puis-je importer ma propre liste de prix?",
    "contact.faq4A": "Oui. Depuis la section Paramètres → Liste de prix, vous pouvez saisir vos propres prix personnalisés que l'IA utilisera comme référence pour vos soumissions.",
    "contact.ctaTitle": "Vous n'avez pas encore de compte?",
    "contact.ctaBody": "Essayez QuoteAI gratuitement — aucune carte de crédit requise.",
    "contact.ctaButton": "Créer un compte gratuit",

