    "seo.guide.heading": "Guide complet : comment créer une soumission professionnelle",
    "seo.guide.subtitle": "Suivez ces 5 étapes pour créer une soumission que votre client signera tout de suite",
    "seo.guide.step1Title": "Rassemblez les informations sur le projet",
    "seo.guide.step1Body": "Avant de commencer, assurez-vous d'avoir : le type d'intervention, les dimensions approximatives (pi², pi linéaire, unités), les matériaux demandés par le client, et ses coordonnées (nom, adresse, courriel). Avec quoteai, vous pouvez tout noter directement depuis votre téléphone pendant la visite.",
    "seo.guide.step2Title": "Définissez les postes de coût",
    "seo.guide.step2Body": "Une soumission professionnelle sépare la main-d'œuvre des matériaux. Chaque poste doit avoir : une description détaillée, une unité de mesure (pi², pi linéaire, heures, forfait), une quantité, un prix unitaire et un montant. L'IA de quoteai génère cette structure automatiquement à partir de votre description.",
    "seo.guide.step3Title": "Appliquez le bon taux de taxe",
    "seo.guide.step3Body": "Les taxes varient selon la province au Canada — TPS, TVH ou TPS+TVQ selon l'endroit où vous travaillez. Une erreur de taxe peut coûter cher. quoteai applique automatiquement le bon taux selon le travail et l'endroit décrits.",
    "seo.guide.step4Title": "Ajoutez vos modalités de paiement",
    "seo.guide.step4Body": "Précisez toujours les modalités : acompte requis (p. ex. 30 % à l'acceptation), solde à la fin des travaux, moyens de paiement acceptés (virement Interac, chèque, carte), délai d'exécution prévu et durée de validité de la soumission (habituellement 30 jours).",
    "seo.guide.step5Title": "Envoyez la soumission au client",
    "seo.guide.step5Body": "Le PDF est le meilleur format : il ne peut pas être modifié par accident et s'ouvre sur n'importe quel appareil. Envoyez-le par courriel ou WhatsApp. Avec quoteai, téléchargez le PDF en un clic, déjà mis en forme avec votre en-tête et votre logo.",

